package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/staff") public class StaffController{private final StaffService s;public StaffController(StaffService s){this.s=s;}@PostMapping public ResponseEntity<StaffDTO> create(@Valid @RequestBody StaffDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<StaffDTO> all(){return s.all();}@GetMapping("/{id}") public StaffDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public StaffDTO update(@PathVariable Long id,@Valid @RequestBody StaffDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
